attempts.script:
# Ensure output directory exists
file mkdir outputs

# Get the clock port
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: Clock port clk not found"
    exit 1
}

# Get the net driven by the clock port
set clk_net [get_nets -of [get_pins -of $clk_port]]
if { [llength $clk_net] == 0 } {
    puts "Error: Net driven by clk port not found"
    exit 1
}
set clk_net [lindex $clk_net 0]

# Find the root buffer (Level 1)
# The root buffer is an instance connected to the clk_net at its input pin.
# We look for instances connected to clk_net that are buffers.
set all_insts [get_cells -of $clk_net]
set root_buf_inst ""
foreach inst $all_insts {
    # Check if instance is a buffer
    set cell_name [get_property [get_lib_cell $inst] name]
    # Heuristic: Buffer cells usually end in X# or are in the buffer library
    # The prompt specifies BUF_X4. Let's check if it's a buffer type.
    # A more robust way is to check if it has an input pin connected to clk_net
    set inst_pins [get_pins -of $inst]
    foreach pin $inst_pins {
        set pin_nets [get_nets -of $pin]
        if { [lsearch -exact $pin_nets $clk_net] != -1 } {
            # This pin is connected to clk_net. Is it an input pin?
            # In standard cells, input pins are usually A, B, etc.
            set pin_name [get_name $pin]
            if { [string match "*A*" $pin_name] || [string match "*B*" $pin_name] || [string match "*C*" $pin_name] } {
                set root_buf_inst $inst
                break
            }
        }
    }
    if { $root_buf_inst != "" } break
}

if { $root_buf_inst == "" } {
    puts "Error: Root clock buffer not found"
    exit 1
}

# Get the set of all registers
set all_registers [get_cells -hierarchical -filter "is_register==1"]
set reg_names [list]
foreach reg $all_registers {
    lappend reg_names [get_name $reg]
}

# Prepare output file
set output_file "outputs/ct06_clock_tree.txt"
set fp [open $output_file w]

# BFS to traverse the clock tree
# Queue elements: {instance_name level}
set queue [list [list $root_buf_inst 1]]
set processed_buffers [list]
set results [list]

# Helper to get output pin of a buffer
# For BUF_X4, output is Z. We should verify or try common names.
# Let's assume Z for standard buffers. If not, we might need to check.
# We can also get the output pin by finding the pin connected to the output net.
# But we need to know the output net first? No, we need to find the output pin to get the net.
# Actually, we can iterate all pins of the buffer, find the one that is NOT an input.
# Or, since we know it's a buffer, we can look for the pin that drives nets.

while { [llength $queue] > 0 } {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set inst_name [lindex $current 0]
    set level [lindex $current 1]

    # Skip if already processed
    if { [lsearch -exact $processed_buffers $inst_name] != -1 } {
        continue
    }
    lappend processed_buffers $inst_name

    # Get the instance object
    set inst_obj [get_cells $inst_name]
    set cell_obj [get_lib_cell $inst_obj]
    set cell_name [get_property $cell_obj name]

    # Find output pin
    # For a buffer, there is typically one output pin.
    # We can find it by checking which pin is not connected to an input net from another buffer/port?
    # Easier: Get all pins, exclude inputs.
    set pins [get_pins -of $inst_obj]
    set out_pin ""
    foreach pin $pins {
        set pin_name [get_name $pin]
        # Common output pin names: Z, Y, O
        if { [string match "Z" $pin_name] || [string match "Y" $pin_name] || [string match "O" $pin_name] } {
            set out_pin $pin
            break
        }
    }

    # If no standard output pin found, try to find pin that drives nets
    if { $out_pin == "" } {
        foreach pin $pins {
            set pin_nets [get_nets -of $pin]
            if { [llength $pin_nets] > 0 } {
                # Check if this pin is an input
                # Input pins are usually A, B, C...
                set pin_name [get_name $pin]
                if { ![string match "*A*" $pin_name] && ![string match "*B*" $pin_name] && ![string match "*C*" $pin_name] } {
                    set out_pin $pin
                    break
                }
            }
        }
    }

    if { $out_pin == "" } {
        # This buffer has no output? Skip.
        continue
    }

    set out_net [get_net -of $out_pin]

    # Count register sinks
    # Get all pins connected to the output net
    set connected_pins [get_pins -of $out_net]
    set reg_sink_count 0
    foreach c_pin $connected_pins {
        # Check if this pin is a clock pin of a register
        set c_inst [get_property [get_parent $c_pin] name]
        set c_inst_obj [get_cells $c_inst]

        # Check if instance is a register
        if { [lsearch -exact $reg_names $c_inst] != -1 } {
            # Check if pin is a clock pin
            # Usually clock pins are named CLK
            set c_pin_name [get_name $c_pin]
            if { [string match "CLK" $c_pin_name] || [string match "*clk*" $c_pin_name] } {
                incr reg_sink_count
            }
        }
    }

    # Add to results
    lappend results "$inst_name $cell_name $level $reg_sink_count"

    # Find downstream buffers
    # Get all pins connected to the output net
    foreach c_pin $connected_pins {
        set c_inst [get_property [get_parent $c_pin] name]
        set c_inst_obj [get_cells $c_inst]
        set c_cell_name [get_property [get_lib_cell $c_inst_obj] name]

        # Check if downstream instance is a buffer
        # We can check if the cell name is in the list of buffer cells.
        # The prompt says BUF_X4. Let's assume any cell with "BUF" in name or specifically BUF_X4.
        # To be safe, let's check if it's a buffer type.
        # We can check if the cell is in the library and is a buffer.
        # A simple heuristic: if the cell name starts with BUF or CLKBUF.
        if { [string match "BUF*" $c_cell_name] || [string match "CLKBUF*" $c_cell_name] } {
            # Check if this instance is an input pin of the buffer
            # The pin c_pin is connected to the output net of the current buffer.
            # If c_pin is an input pin of c_inst, then c_inst is driven by current buffer.
            set c_pin_name [get_name $c_pin]
            # Input pins are usually A, B, C...
            if { [string match "*A*" $c_pin_name] || [string match "*B*" $c_pin_name] || [string match "*C*" $c_pin_name] } {
                if { [lsearch -exact $processed_buffers $c_inst] == -1 } {
                    lappend queue [list $c_inst [expr {$level + 1}]]
                }
            }
        }
    }
}

# Write results to file
foreach line $results {
    puts $fp $line
}

close $fp

# Ensure the output directory exists
if {[file exists outputs] == 0} {
    file mkdir outputs
}

# Open the output file
set output_file "outputs/io_ports.txt"
set fp [open $output_file w]

# Get all top-level ports
set ports [get_ports]

foreach port $ports {
    # Get the port name
    set port_name [get_property NAME $port]

    # Get the direction
    set direction [get_property DIRECTION $port]

    # Normalize direction to lowercase
    set direction [string tolower $direction]

    # Get the width of the port
    set width [get_property WIDTH $port]

    if {$width == 1} {
        # Single bit port
        puts $fp "$port_name $direction"
    } else {
        # Multi-bit bus port
        for {set i 0} {$i < $width} {incr i} {
            puts $fp "${port_name}[$i] $direction"
        }
    }
}

# Close the file
close $fp

# Ensure the output directory exists
file mkdir outputs

# Export the current gate-level netlist including CTS buffers to outputs/gcd_netlist.v
# The design is already loaded with CTS performed.
# write_verilog exports the structural netlist of the current design.
write_verilog -no_format outputs/gcd_netlist.v

# Optional: Verify the file was created (for debugging/logging purposes, not strictly required)
if {[file exists outputs/gcd_netlist.v]} {
    puts "Successfully exported netlist to outputs/gcd_netlist.v"
} else {
    puts "Error: Failed to export netlist to outputs/gcd_netlist.v"
}

# Ensure the outputs directory exists
file mkdir outputs

# Get all instances in the design
set instances [get_cells -hierarchical -quiet *]

# Associative array to store cell counts
array set cell_counts {}

# Iterate through each instance
foreach inst $instances {
    # Get the cell name (library cell type) of the instance
    set cell_name [get_property $inst CELL]

    # Skip if cell_name is empty or invalid
    if {$cell_name eq ""} {
        continue
    }

    # Exclude physical-only cells: TAPCELL, FILLCELL, and potentially IO/PAD cells
    # The prompt specifically mentions tap/endcap and filler. 
    # "Standard-cell type" usually implies logic cells. 
    # IO pads and macro cells are typically not counted as standard cell usage.
    # We will exclude TAPCELL*, FILLCELL*, PAD*, and IO* patterns.
    if {[string match -nocase "TAPCELL*" $cell_name]} {
        continue
    }
    if {[string match -nocase "FILLCELL*" $cell_name]} {
        continue
    }
    if {[string match -nocase "PAD*" $cell_name]} {
        continue
    }
    if {[string match -nocase "IO*" $cell_name]} {
        continue
    }

    # Increment the count for this cell type
    if {[info exists cell_counts($cell_name)]} {
        incr cell_counts($cell_name)
    } else {
        set cell_counts($cell_name) 1
    }
}

# Open the output file
set outfile [open outputs/cell_usage.txt w]

# Variable to store total count
set total_count 0

# Write each cell type and its count
foreach cell_name [lsort [array names cell_counts]] {
    set count $cell_counts($cell_name)
    puts $outfile "$cell_name $count"
    incr total_count $count
}

# Write the total count
puts $outfile "total $total_count"

# Close the output file
close $outfile

# Get all nets
set all_nets [get_nets]

# Identify and exclude power and ground nets
set excluded_nets {}
foreach net $all_nets {
    if {[get_property $net is_power] || [get_property $net is_ground]} {
        lappend excluded_nets $net
    }
}

# Identify and exclude clock net
# Find the net connected to the clock port 'clk'
set clk_port [get_ports clk]
if {$clk_port != ""} {
    set clk_net [get_nets -of_objects $clk_port]
    if {$clk_net != ""} {
        lappend excluded_nets $clk_net
    }
}

# Filter nets to only signal nets
set signal_nets {}
foreach net $all_nets {
    if {$net ni $excluded_nets} {
        lappend signal_nets $net
    }
}

# Create a list to store {fanout net_name}
set fanout_list {}

foreach net $signal_nets {
    # Get the fanout using OpenSTA command via 'sta'
    # get_fanout returns a list of pins/instances. The number of items is the fanout.
    # However, get_fanout might return duplicates if a pin is loaded multiple times? 
    # No, it returns unique sinks.
    # Let's use get_fanout -only_cells to get instances, but the definition says "input pins of cell instances".
    # So we need the count of pins.
    # get_fanout returns pins.
    set fanout_pins [sta "get_fanout -from $net"]
    set fanout_count [llength $fanout_pins]

    # Get net name
    set net_name [get_name $net]

    # Add to list
    lappend fanout_list "$fanout_count $net_name"
}

# Sort by fanout descending
# We need to sort numerically by the first field
set sorted_list [lsort -integer -decreasing -index 0 $fanout_list]

# Take top 5
set top_5 [lrange $sorted_list 0 4]

# Write to output file
set output_file "outputs/high_fanout_nets.txt"
file mkdir outputs
set stream [open $output_file "w"]
foreach entry $top_5 {
    # Entry is "fanout net_name"
    set fanout [lindex $entry 0]
    set net_name [lindex $entry 1]
    puts $stream "$net_name $fanout"
}
close $stream

# Ensure outputs directory exists
file mkdir outputs

# 1. Analyze Flip-Flop Types
set flops [all_registers -cells -edge_triggered]
set flop_counts [dict create]
set total_flops 0

foreach flop $flops {
    set cell_type [get_property [get_cell $flop] type]
    dict incr flop_counts $cell_type
    incr total_flops
}

# Write flop_types.txt
set f [open "outputs/flop_types.txt" w]
foreach {cell_type count} [dict sorted_elements $flop_counts] {
    puts $f "$cell_type $count"
}
puts $f "total $total_flops"
close $f

# 2. Analyze Flip-Flop Clock Drivers
# Map: net_name -> list of driving instance names
set net_drivers [dict create]

# Get all output pins of all cells
set all_cells [get_cells *]
set all_out_pins [get_pins -of_objects $all_cells -output]

foreach pin $all_out_pins {
    # Get the net connected to this output pin
    set nets [get_nets -of_objects $pin]
    if {[llength $nets] > 0} {
        set net [lindex $nets 0]
        set net_name [get_property $net name]

        # Get the driving instance name
        set parent [get_parent $pin]
        set inst_name [get_property $parent name]

        # Add to the list for this net
        if {[dict exists $net_drivers $net_name]} {
            set drivers [dict get $net_drivers $net_name]
            lappend drivers $inst_name
            dict set net_drivers $net_name $drivers
        } else {
            dict set net_drivers $net_name [list $inst_name]
        }
    }
}

# Count flops per driver
set driver_counts [dict create]

foreach flop $flops {
    # Get the clock pin of the flop
    set clk_pins [get_pins -of_objects $flop -clock_pins]
    if {[llength $clk_pins] > 0} {
        set clk_pin [lindex $clk_pins 0]
        set nets [get_nets -of_objects $clk_pin]
        if {[llength $nets] > 0} {
            set net [lindex $nets 0]
            set net_name [get_property $net name]

            if {[dict exists $net_drivers $net_name]} {
                set drivers [dict get $net_drivers $net_name]
                foreach driver_inst $drivers {
                    dict incr driver_counts $driver_inst
                }
            }
        }
    }
}

# Write flop_clock_drivers.txt
set f2 [open "outputs/flop_clock_drivers.txt" w]
foreach {inst_name count} [dict sorted_elements $driver_counts] {
    puts $f2 "$inst_name $count"
}
close $f2

# Run global routing
global_route

# Capture the wirelength report
set report [report_wire_length -global_route]

# Parse the total wirelength from the report
# The format is typically "[INFO GRT-0018] Total wirelength: <value> um"
set total_wirelength ""
foreach line [split $report "\n"] {
    if {[string match "*Total wirelength:*" $line]} {
        # Extract the number after "Total wirelength:"
        if {[regexp {Total wirelength:\s+([0-9]+\.?[0-9]*)\s+um} $line match total_wirelength]} {
            break
        }
    }
}

# Write the result to the output file
if {$total_wirelength ne ""} {
    set file [open "outputs/grt_wirelength.txt" w]
    puts $file $total_wirelength
    close $file
} else {
    puts "Error: Could not parse total wirelength from global routing report."
}

# Open the output file
set outfile [open "outputs/ct06_clock_tree.txt" w]

# 1. Identify the clock port and root buffer
set clk_port [get_ports clk]
set clk_net [get_nets -of_objects $clk_port]

# The root buffer is the instance connected to the clk port net
# It should be a BUF_X4
set root_buffers [get_cells -of_objects [get_nets $clk_net]]
# Filter for BUF_X4
set root_buf [lindex [get_cells -of_objects [get_nets $clk_net] -filter "ref_name==BUF_X4"] 0]

if { [string equal $root_buf ""] } {
    puts "ERROR: Could not find root BUF_X4 driven by clk"
    exit 1
}

# 2. BFS to traverse the clock tree
# Queue: list of {instance_name level}
set queue [list [list $root_buf 1]]
set visited [list $root_buf]
set results [list]

while { [llength $queue] > 0 } {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set inst [lindex $current 0]
    set level [lindex $current 1]

    # Get the output pin of this buffer
    # BUF_X4 has output pin Y
    set out_pin [get_pins -of_objects $inst -filter "direction==out"]
    if { [string equal $out_pin ""] } {
        continue
    }

    set out_net [get_net -of_objects $out_pin]

    # Find all cells connected to this output net
    set connected_cells [get_cells -of_objects $out_net]

    set register_sinks 0
    set next_buffers [list]

    foreach cell $connected_cells {
        # Check if it's a sequential cell (flip-flop)
        if { [is_sequential $cell] } {
            # Check if it has an input clock pin connected to this net
            set pins [get_pins -of_objects $cell -filter "direction==in && port_class==clock"]
            foreach pin $pins {
                # Check if this pin is connected to out_net
                # get_nets -of_objects $pin should return the net
                set pin_nets [get_nets -of_objects $pin]
                if { [string equal $pin_nets $out_net] } {
                    incr register_sinks
                }
            }
        }

        # Check if it's a BUF_X4 buffer (next level in tree)
        if { [string equal [get_property $cell ref_name] "BUF_X4"] } {
            set cell_name [get_name $cell]
            if { ![lsearch -exact $visited $cell_name] != -1 } {
                lappend visited $cell_name
                lappend next_buffers $cell
            }
        }
    }

    # Record result
    set inst_name [get_name $inst]
    set cell_name [get_property $inst ref_name]
    lappend results "$inst_name $cell_name $level $register_sinks"

    # Add next buffers to queue
    foreach next_buf $next_buffers {
        set next_level [expr {$level + 1}]
        lappend queue [list $next_buf $next_level]
    }
}

# Write results to file
foreach line $results {
    puts $outfile $line
}

close $outfile

# Open the output file
set output_file [open "outputs/io_ports.txt" w]

# Get all top-level ports of the current design
set ports [get_ports]

foreach port $ports {
    # Get the port name
    set port_name [get_property NAME $port]

    # Get the direction (input or output)
    set direction [get_property DIRECTION $port]

    # Get the width of the port
    set width [get_property WIDTH $port]

    if {$width > 1} {
        # Expand multi-bit ports bit by bit
        for {set i 0} {$i < $width} {incr i} {
            puts $output_file "$port_name[$i] $direction"
        }
    } else {
        # Single-bit port
        puts $output_file "$port_name $direction"
    }
}

# Close the output file
close $output_file

# Ensure the outputs directory exists
file mkdir outputs

# Initialize an associative array to store cell counts
set cell_counts {}
set total_count 0

# Get all instances in the design
set instances [get_cells -hierarchical *]

foreach inst $instances {
    # Get the cell name (library reference) for this instance
    set cell_name [get_property $inst CELLS]

    # Skip if cell_name is empty or invalid
    if {![string length $cell_name]} {
        continue
    }

    # Check if the cell is a physical-only cell
    # Based on platform description:
    # Tap/endcap: TAPCELL_X1
    # Fillers: FILLCELL_X1 ... FILLCELL_X32
    # We exclude cells matching these patterns.
    if {[string match -nocase "TAPCELL*" $cell_name]} {
        continue
    }
    if {[string match -nocase "ENDCAP*" $cell_name]} {
        continue
    }
    if {[string match -nocase "FILLCELL*" $cell_name]} {
        continue
    }

    # Increment the count for this cell type
    if {[info exists cell_counts($cell_name)]} {
        incr cell_counts($cell_name)
    } else {
        set cell_counts($cell_name) 1
    }

    incr total_count
}

# Open the output file
set output_file "outputs/cell_usage.txt"
set fp [open $output_file w]

# Write each cell type and its count
foreach cell_name [lsort [array names cell_counts]] {
    puts $fp "$cell_name $cell_counts($cell_name)"
}

# Write the total count
puts $fp "total $total_count"

# Close the output file
close $fp

# Create output directory if not exists
file mkdir outputs

# 1. Analyze Flip-Flop Types
set all_flops [all_registers -cells -edge_triggered]
set flop_counts [dict create]
set total_flops 0

foreach inst $all_flops {
    set cell_name [get_property [get_instance $inst] CELL]
    if {[dict exists $flop_counts $cell_name]} {
        dict set flop_counts $cell_name [expr {[dict get $flop_counts $cell_name] + 1}]
    } else {
        dict set flop_counts $cell_name 1
    }
    incr total_flops
}

# Write flop_types.txt
set f [open "outputs/flop_types.txt" w]
foreach {cell count} [dict sorted $flop_counts] {
    puts $f "$cell $count"
}
puts $f "total $total_flops"
close $f

# 2. Analyze Clock Drivers
set driver_counts [dict create]

foreach inst $all_flops {
    # Get the cell type to know the clock pin name
    set cell_name [get_property [get_instance $inst] CELL]
    set pins [get_pins -of [get_cells $cell_name]]

    # Find clock pins. Usually CK, but could be CLK. 
    # We look for pins with DIRECTION==IN and NAME matching CK or CLK
    set clock_pins [get_pins -of [get_cells $cell_name] -filter "DIRECTION==IN && (NAME==CK || NAME==CLK)"]

    foreach cp $clock_pins {
        # Get the net connected to this clock pin
        set net_name [get_property $cp NET]
        set net [get_nets $net_name]

        # Find the driving pin of this net
        # The driving pin is an output pin of some cell instance connected to this net
        set driving_pins [get_pins -of $net -filter "DIRECTION==OUT"]

        if {[llength $driving_pins] > 0} {
            set drv_pin [lindex $driving_pins 0]
            set drv_inst [get_property $drv_pin INSTANCE]

            if {[dict exists $driver_counts $drv_inst]} {
                dict set driver_counts $drv_inst [expr {[dict get $driver_counts $drv_inst] + 1}]
            } else {
                dict set driver_counts $drv_inst 1
            }
        }
    }
}

# Write flop_clock_drivers.txt
set f2 [open "outputs/flop_clock_drivers.txt" w]
foreach {inst count} [dict sorted $driver_counts] {
    puts $f2 "$inst $count"
}
close $f2

# Estimate parasitics from the existing global routing
estimate_parasitics -global_routing

# Report the worst setup slack (negative value indicates violation)
set wns [report_worst_slack -min -digits 4]

# Extract the numeric value from the report
# The format is typically: "WNS: <value> ns" or just "<value>"
# We use regexp to get the number
if {[regexp {WNS:\s+(-?[0-9]+\.[0-9]+)} $wns match wns_val]} {
    # Round to 4 decimal places
    set wns_rounded [format "%.4f" $wns_val]
} else {
    # Fallback: try to find any number
    if {[regexp {(-?[0-9]+\.[0-9]+)} $wns match wns_val]} {
        set wns_rounded [format "%.4f" $wns_val]
    } else {
        error "Could not parse WNS from report: $wns"
    }
}

# Create the outputs directory if it doesn't exist
file mkdir outputs

# Write the result to the output file
set fid [open "outputs/wns_grt.txt" w]
puts $fid $wns_rounded
close $fid

# Create output directory
file mkdir outputs

# 1. Identify all clock nets
# Start with the net driven by the clock port clk
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: Clock port clk not found"
    exit 1
}
set clk_net [get_nets -of_objects [get_pins $clk_port]]
if { [llength $clk_net] == 0 } {
    puts "Error: Net driven by clk port not found"
    exit 1
}

set clock_nets [list [lindex $clk_net 0]]
set changed 1
while { $changed } {
    set changed 0
    set new_nets [list]
    foreach net $clock_nets {
        # Get all pins driven by this net
        set driven_pins [get_pins -of_objects [get_nets $net]]
        # We need to find cells driven by this net, then their output pins
        # Actually, get_pins -of_objects [get_nets $net] returns pins ON the net
        # We want pins OF cells that are driven BY the net
        # So we get cells connected to the net, then their output pins
        set cells [get_cells -of_objects [get_nets $net]]
        foreach cell $cells {
            # Get output pins of this cell
            set out_pins [get_pins -filter "DIRECTION==OUTPUT" -of_objects $cell]
            foreach pin $out_pins {
                # Check if the cell is a clock buffer or inverter (part of clock tree)
                # Or if the net is a clock net?
                # In a CTS design, clock nets drive CLKBUF and INV cells.
                set cell_type [get_property TYPE $cell]
                if { [regexp {^CLKBUF|^INV} $cell_type] } {
                    set driven_net [get_nets -of_objects $pin]
                    if { [llength $driven_net] > 0 } {
                        set n [lindex $driven_net 0]
                        if { ![lsearch -exact $clock_nets $n] != -1 } {
                            lappend new_nets $n
                            set changed 1
                        }
                    }
                }
            }
        }
    }
    # Add new nets to clock_nets
    foreach n $new_nets {
        if { ![lsearch -exact $clock_nets $n] != -1 } {
            lappend clock_nets $n
        }
    }
}

# 2. Report wirelength
# Use report_wire_length to get the data
# We will capture the output
set report_output [report_wire_length -net $clock_nets -global_route]

# 3. Parse the output and write to file
# The output format is typically:
# Net Name          Wirelength (um)
# net1              123.45
# net2              67.89

set out_file "outputs/clock_gr_wirelength.txt"
set fp [open $out_file w]

# Skip header lines if any
set lines [split $report_output "\n"]
set found_header 0
foreach line $lines {
    # Check if line contains "Net Name"
    if { [regexp {Net Name} $line] } {
        set found_header 1
        continue
    }
    if { $found_header } {
        # Parse net name and wirelength
        # Format is usually space separated, possibly multiple spaces
        if { [regexp {^(\S+)\s+(\S+)} $line match net_name wirelength] } {
            puts $fp "$net_name $wirelength"
        }
    }
}

close $fp

puts "Clock GR wirelength report written to $out_file"

# Ensure output directory exists
file mkdir outputs

# Open the output file
set out_file [open "outputs/io_ports.txt" w]

# Get the list of ports
# report_ports returns a list of strings, each string is a port entry.
# The format is typically: "port_name direction"
# However, in some versions, it might be a list of lists or just a string with newlines.
# Let's use catch to capture the output string.

set port_info [report_ports]

# Split into lines
set lines [split $port_info "\n"]

foreach line $lines {
    # Trim whitespace
    set line [string trim $line]

    # Skip empty lines
    if { $line eq "" } { continue }

    # Split by whitespace to get name and direction
    # Some ports might have extra info, but usually it's just name and direction
    set parts [regexp -all -inline {\S+} $line]

    if { [llength $parts] < 2 } {
        continue
    }

    set port_name [lindex $parts 0]
    set direction [lindex $parts 1]

    # Normalize direction to lowercase
    set direction [string tolower $direction]

    # Check if the port name contains a range
    if { [regexp {\[([^\]]+)\]} $port_name match range_str] } {
        # It's a bus or bit-select
        # Extract base name
        set base_name [string trimright $port_name "[0-9:]" ]
        # Actually, string trimright might be tricky if the name ends with numbers.
        # Better approach: split by the first '['
        set bracket_idx [string first "[" $port_name]
        set base_name [string range $port_name 0 [expr {$bracket_idx - 1}]]
        set range_part [string range $port_name $bracket_idx end]

        # Parse the range
        # range_part is like "[31:0]" or "[0]"
        set inner_range [string trim $range_part "[]"]

        if { [regexp {^(\d+):(\d+)$} $inner_range match msb lsb] } {
            # It's a range msb:lsb
            set start [string trimleft $msb]
            set end [string trimleft $lsb]

            # Determine step
            if { $start > $end } {
                set step -1
            } else {
                set step 1
            }

            # Generate bits
            for { set i $start } { $i != [expr {$end + $step}] } { incr i $step } {
                puts $out_file "$base_name[$i] $direction"
            }
        } elseif { [regexp {^(\d+)$} $inner_range match bit] } {
            # It's a single bit
            set bit [string trimleft $bit]
            puts $out_file "$base_name[$bit] $direction"
        } else {
            # Fallback: treat as single port if parsing fails
            puts $out_file "$port_name $direction"
        }
    } else {
        # Single bit port
        puts $out_file "$port_name $direction"
    }
}

close $out_file

