# Define patterns for physical-only cells to exclude
# These are standard in Nangate45: Tap, Endcap, and Filler cells
set exclude_patterns {
    TAPCELL*
    ENDCAP*
    FILLCELL*
}

# Get all instances in the design hierarchically
# get_cells returns cells (instances) when used on the design
set all_instances [get_cells -hierarchical *]

# Dictionary to store counts of each cell type
set cell_counts [dict create]
set total_count 0

foreach inst $all_instances {
    # Get the cell name (type) of the instance
    set cell_name [get_property $inst REF]

    # Check if the cell name matches any exclusion pattern
    set is_excluded 0
    foreach pattern $exclude_patterns {
        if {[string match $pattern $cell_name]} {
            set is_excluded 1
            break
        }
    }

    # If not excluded, increment the count
    if {$is_excluded == 0} {
        if {[dict exists $cell_counts $cell_name]} {
            set current_count [dict get $cell_counts $cell_name]
            dict set cell_counts $cell_name [expr {$current_count + 1}]
        } else {
            dict set cell_counts $cell_name 1
        }
        incr total_count
    }
}

# Open the output file
set output_file [open outputs/cell_usage.txt w]

# Write each cell type and its count
# Sort the keys for deterministic output (optional but good practice)
set sorted_keys [lsort [dict keys $cell_counts]]

foreach cell_name $sorted_keys {
    set count [dict get $cell_counts $cell_name]
    puts $output_file "$cell_name $count"
}

# Write the total count
puts $output_file "total $total_count"

