    }

    # Get all pins connected to this net
    set pins_on_net [get_pins -of $net]

    foreach pin $pins_on_net {
        # Check if the pin is an output pin (potential driver)
        set direction [get_property $pin "direction"]
        if {$direction ne "out"} {
