        }

        # Get the instance of this pin
        set inst [get_property $pin "parent_instance"]
        if {$inst eq ""} {
            continue
        }

        # Count this driver
        if {[info exists driver_counts($inst)]} {
            incr driver_counts($inst)
        } else {
            set driver_counts($inst) 1
        }
    }
}

