# Helper procedure to calculate HPWL
proc calc_hpwl {} {
    set total_hpwl 0.0
    set all_nets [all_nets]

    foreach net $all_nets {
        # Skip power and ground nets
        # Check if the net is connected to a power port
        set is_power_net 0
        foreach port [get_ports -of_objects [get_nets $net]] {
            if {[is_port_power $port]} {
                set is_power_net 1
                break
            }
        }
        # Also check if net name suggests power/ground if port check fails or for robustness
        if {[string match -nocase "*VDD*" $net] || [string match -nocase "*VSS*" $net] || [string match -nocase "*GND*" $net] || [string match -nocase "*PWR*" $net]} {
            set is_power_net 1
        }

        if {$is_power_net} {
            continue
        }

        # Get pins for this net
        set pins [get_pins -of_objects [get_nets $net]]

        # Count pins
        set num_pins [llength $pins]

        # Skip nets with less than 2 pins
        if {$num_pins < 2} {
            continue
        }

        # Calculate bounding box of pin centers
        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            # Get the location of the pin
            # The location of an instance pin is the center of its pin shapes.
            # get_pin_location returns the location in the database units (microns typically in OpenROAD)
            set loc [get_pin_location $pin]
            if {$loc != ""} {
                set x [lindex $loc 0]
                set y [lindex $loc 1]

                if {$x < $min_x} { set min_x $x }
                if {$y < $min_y} { set min_y $y }
                if {$x > $max_x} { set max_x $x }
                if {$y > $max_y} { set max_y $y }
            }
        }

        # If any pin location was missing, skip this net (shouldn't happen in legal placement)
        if {$min_x == 1e9} { continue }

        set width [expr {$max_x - $min_x}]
        set height [expr {$max_y - $min_y}]
        set hpwl [expr {$width + $height}]

        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }

    return $total_hpwl
}

