# Get the root clock net
set clk_root_nets [get_nets -of_objects [get_clocks]]
set clock_nets $clk_root_nets

# Queue for BFS traversal
set queue [get_pins -of_objects $clk_root_nets]
set visited_pins {}

while {[llength $queue] > 0} {
    set pin [lindex $queue 0]
    set queue [lrange $queue 1 end]

    if {[lsearch -exact $visited_pins $pin] >= 0} {
        continue
    }
    lappend visited_pins $pin

    # Get the cell driving this pin
    set cell [get_cell -of_objects $pin]

    # Check if this cell is a buffer/inverter (potential clock tree element)
    set cell_type [get_property $cell type]
    if {$cell_type =~ "CLKBUF*" || $cell_type =~ "INV*" || $cell_type =~ "BUF*"} {
        # Get output pins of this cell
        set out_pins [get_pins -direction out -of_objects $cell]
        foreach out_pin $out_pins {
            set out_net [get_net -of_objects $out_pin]
            if {$out_net ni $clock_nets} {
                lappend clock_nets $out_net
                # Add output pins to queue to continue traversal
                lappend queue $out_pin
            }
        }
    }
}

# Remove duplicates
set unique_clock_nets [lsort -unique $clock_nets]

